class Solution {
  public int firstArrivalsBossReceipt(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>seen=new HashSet<>();for(int x:a)if(seen.add(x))out.add(x);}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
